package io.ecosync.gateway;
import java.sql.Types;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;
class ReadQueryTest {
 final ReadQuery builder=new ReadQuery();
 Map<String,Object> table(){return Map.of("schema","sales","name","odd\"table","primaryKey",List.of("id"),"columns",List.of(col("id",Types.INTEGER,"int4"),col("label",Types.VARCHAR,"varchar"),col("amount",Types.DECIMAL,"numeric"),col("active",Types.BOOLEAN,"bool"),col("created",Types.TIMESTAMP,"timestamp"),col("uid",Types.OTHER,"uuid")));}
 static Map<String,Object> col(String name,int type,String typeName){return Map.of("name",name,"jdbcType",type,"typeName",typeName,"supported",true,"precision",type==Types.DECIMAL?12:128,"scale",2);}
 @Test void dialectIdentifiersAreQuotedAndInjectionValuesRemainParameters(){for(boolean mysql:List.of(false,true)){String attack="' OR 1=1; DROP TABLE items; --";var q=builder.build(mysql,table(),List.of("id","label"),Map.of("columns",List.of("label"),"filters",List.of(Map.of("column","label","operator","EQ","value",attack)),"limit",2));assertThat(q.sql()).doesNotContain(attack).contains("LIMIT ? OFFSET ?").contains(mysql?"`sales`.`odd\"table`":"\"sales\".\"odd\"\"table\"");assertThat(q.parameters()).containsExactly(attack,3,0);assertThat(q.sql()).contains(mysql?"`id` ASC":"\"id\" ASC");}}
 @Test void unknownUnapprovedAndInjectedIdentifiersNeverProduceSql(){for(String bad:List.of("secret","id; DELETE FROM items","pg_catalog.pg_authid","count(*)","label DESC; DROP TABLE x")){assertThatThrownBy(()->builder.build(false,table(),List.of("id","label"),Map.of("columns",List.of(bad)))).isInstanceOf(GatewayFailure.class);assertThatThrownBy(()->builder.build(true,table(),List.of("id","label"),Map.of("columns",List.of("id"),"order",List.of(Map.of("column",bad,"direction","ASC"))))).isInstanceOf(GatewayFailure.class);}}
 @Test void requestOperatorsAndEveryBoundAreStrict(){for(Map<String,Object> request:List.<Map<String,Object>>of(Map.of("columns",List.of("id"),"sql","DELETE"),Map.of("columns",List.of("id"),"limit",101),Map.of("columns",List.of("id"),"offset",10001),Map.of("columns",List.of("id"),"limit",1.5),Map.of("columns",List.of("id"),"filters",List.of(Map.of("column","id","operator","IN","value","1"))),Map.of("columns",List.of("id"),"order",List.of(Map.of("column","id","direction","ASC;DELETE")))))assertThatThrownBy(()->builder.build(false,table(),List.of("id"),request)).isInstanceOf(GatewayFailure.class);}
 @Test void numericBooleanUuidAndUtcTimeTypesRejectIncompatibleValues(){for(Object bad:List.of(1,"1 OR 1=1","2147483648","1.2"))assertThatThrownBy(()->ReadQuery.value(col("id",Types.INTEGER,"int4"),bad)).isInstanceOf(GatewayFailure.class);assertThat(ReadQuery.value(col("id",Types.INTEGER,"int4"),"10")).isEqualTo(new java.math.BigDecimal("10"));assertThat(ReadQuery.value(col("active",Types.BOOLEAN,"bool"),true)).isEqualTo(true);assertThatThrownBy(()->ReadQuery.value(col("active",Types.BOOLEAN,"bool"),"true")).isInstanceOf(GatewayFailure.class);assertThatThrownBy(()->ReadQuery.value(col("created",Types.TIMESTAMP,"timestamp"),"2026-10-01T00:00:00")).isInstanceOf(GatewayFailure.class);assertThatThrownBy(()->ReadQuery.value(col("uid",Types.OTHER,"uuid"),"x")).isInstanceOf(GatewayFailure.class);}
 @Test void primaryKeyMustBeApprovedAndOrderingAlwaysHasStableTieBreakers(){assertThatThrownBy(()->builder.build(false,table(),List.of("label"),Map.of("columns",List.of("label")))).isInstanceOf(GatewayFailure.class);var q=builder.build(true,table(),List.of("id","label"),Map.of("columns",List.of("label"),"order",List.of(Map.of("column","label","direction","DESC"))));assertThat(q.sql()).contains("ORDER BY `label` DESC,`id` ASC");}
 @Test void nullFiltersNeverBindUserExpressions(){var q=builder.build(false,table(),List.of("id","label"),Map.of("columns",List.of("id"),"filters",List.of(Map.of("column","label","operator","IS_NULL"))));assertThat(q.sql()).contains("\"label\" IS NULL");assertThat(q.parameters()).containsExactly(51,0);}
}
